      expect(await mandar(tel, '2')).toBe('pergunta');
      expect(await mandar(tel, NOME_B)).toBe('pergunta');
      expect((await q(`select tenant_id from mister_conversa where telefone = $1`, [tel]))[0].tenant_id).toBe(A);
