      const [a] = (await consoleDoMister.empresas(MARCA)).empresas;
      expect(a).toMatchObject({ ia: { origem: 'incluida', provedor: null }, situacao: 'funcionando', usoUsd: 1.1 });
      expect((await consoleDoMister.empresas('%')).empresas).toEqual([]);
