        await q(`update fiscal_credencial set cert_valido_ate = now() + interval '3 days 1 hour' where tenant_id = $1 and unidade_id = $2`, [A, lojaDeA]);
        expect(await avisos.volta([A])).toMatchObject({ abertos: 1, resolvidos: 1 });
