        numero.pedidos.length = 0;
        expect(await tocar(telCarlos, `doc:volta:${d.id}:2026-11-25`)).toBe('respondeu_proposta');
        expect((await titulos())[0].vencimento).toBe('2026-11-30');
        // Pela conversa: o "Desfazer" vai no balão da resposta.
