        numero.responder = (p) => (p.url === `${GRAPH}/555666777` ? { status: 200, corpo: { url: 'https://arquivos.exemplo.com/boleto.jpg', mime_type: 'image/jpeg', file_size: 10 } } : undefined);
        numero.pedidos.length = 0;
